import AbstractApiService from 'src/services/abstractApiService';
import { FULL_TEXT_SEARCH_API_URL, DOCNET_URL } from 'pages/APIs';
import { whenRegionReady } from 'src/pages/api-base-url';
import axios from 'axios';
import { useAuthTokenStore } from 'src/store/User/auth_token.store';
import { useUserStore } from 'src/store/main';

/**
 * Interface for ERP indexing setting item
 */
export interface ERPIndexingSetting {
  entity_type: string;
  enabled: boolean;
  pref_key: string;
  vector_enabled: boolean;
  vector_pref_key: string;
}

/**
 * Interface for the response from get ERP indexing settings
 */
export interface ERPIndexingSettingsResponse {
  success: boolean;
  settings: ERPIndexingSetting[];
  message?: string;
}

/**
 * Interface for entity type statistics
 */
export interface EntityTypeStat {
  entity_type: string;
  display_name: string;
  total_indexed: number;
  with_vector: number;
  text_only: number;
  in_database: number;  // Count from source database (lookup_table)
  indexing_enabled: boolean;
  vector_enabled: boolean;
}

/**
 * Interface for the response from get ERP stats
 */
export interface ERPStatsResponse {
  success: boolean;
  org_id: string;
  index_name: string;
  entity_stats: EntityTypeStat[];
  totals: {
    total_indexed: number;
    with_vector: number;
    text_only: number;
    in_database: number;
  };
  message?: string;
}

export interface TemplateGenerationStatus {
  index_name: string;
  index_exists: boolean;
  current_generation: number;
  target_generation: number;
  rebuild_required: boolean;
  mapping_meta?: Record<string, unknown>;
}

export interface FulltextTemplateVersions {
  document: TemplateGenerationStatus;
  vector: TemplateGenerationStatus;
  text?: TemplateGenerationStatus;
  rebuild_required: boolean;
  reason?: string | null;
}

/**
 * API Service for Fulltext Search ERP indexing settings
 *
 * Manages which ERP entity types (vendors, customers, POs, etc.)
 * are indexed in OpenSearch for fulltext search functionality.
 */
export default class FulltextSettingsApiService extends AbstractApiService {
  public constructor() {
    super({});
  }

  /**
   * Get all ERP indexing settings for the organization
   *
   * @returns Promise with settings array containing entity_type, enabled, and pref_key
   */
  public async getERPIndexingSettings(): Promise<ERPIndexingSettingsResponse> {
    const formData = new FormData();
    return super.post(
      `${FULL_TEXT_SEARCH_API_URL}/opensearch/admin/erp-settings`,
      formData
    );
  }

  /**
   * Update a single ERP indexing setting
   *
   * @param entityType - The ERP entity type (vendor, customer, purchase_order, etc.)
   * @param enabled - Whether indexing is enabled for this entity type (optional)
   * @param vectorEnabled - Whether vector storage is enabled for this entity type (optional)
   * @returns Promise with success status
   */
  public async updateERPIndexingSetting(
    entityType: string,
    enabled?: boolean,
    vectorEnabled?: boolean
  ): Promise<{ success: boolean; message?: string }> {
    const formData = new FormData();
    formData.append('entity_type', entityType);
    if (enabled !== undefined) {
      formData.append('enabled', String(enabled));
    }
    if (vectorEnabled !== undefined) {
      formData.append('vector_enabled', String(vectorEnabled));
    }

    return super.post(
      `${FULL_TEXT_SEARCH_API_URL}/opensearch/admin/erp-settings/update`,
      formData
    );
  }

  /**
   * Bulk update multiple ERP indexing settings
   *
   * @param settings - Array of settings to update
   * @returns Promise with success status and updated count
   */
  public async bulkUpdateERPIndexingSettings(
    settings: Array<{ entity_type: string; enabled: boolean }>
  ): Promise<{ success: boolean; updated_count: number; message?: string }> {
    const formData = new FormData();
    formData.append('settings', JSON.stringify(settings));

    return super.post(
      `${FULL_TEXT_SEARCH_API_URL}/opensearch/admin/erp-settings/bulk-update`,
      formData
    );
  }

  /**
   * Toggle all ERP indexing settings at once
   *
   * @param enabled - Enable or disable all entity types
   * @returns Promise with success status
   */
  public async toggleAllERPIndexing(
    enabled: boolean
  ): Promise<{ success: boolean; updated_count: number; message?: string }> {
    const formData = new FormData();
    formData.append('enabled', String(enabled));

    return super.post(
      `${FULL_TEXT_SEARCH_API_URL}/opensearch/admin/erp-settings/toggle-all`,
      formData
    );
  }

  /**
   * Get ERP indexing statistics for the organization
   *
   * Returns counts of indexed documents per entity type,
   * including total indexed, with vector, and text-only counts.
   *
   * @returns Promise with stats per entity type and totals
   */
  public async getERPStats(): Promise<ERPStatsResponse> {
    const formData = new FormData();
    return super.post(
      `${FULL_TEXT_SEARCH_API_URL}/opensearch/erp/stats`,
      formData
    );
  }

  /**
   * Get AI indexing statistics for agents with memory enabled
   *
   * Returns counts of indexed documents per AI agent that has
   * memory_enabled=true and an opensearch_index configured.
   *
   * Note: This uses a direct axios call to avoid triggering the main app's
   * 401 token refresh logic when docnet auth fails. The docnet API has
   * separate authentication from the main doc2app API.
   *
   * @returns Promise with stats per agent and totals
   */
  public async getAIIndexingStats(): Promise<AIIndexingStatsResponse> {
    // Use direct axios call to avoid AbstractApiService's 401 handling
    // which triggers token refresh for main app (not applicable to docnet API)
    const authStore = useAuthTokenStore();
    const userStore = useUserStore();
    const token = authStore.getValidatedToken();
    const orgId = userStore.getOrgId();

    try {
      const response = await axios.get(`${DOCNET_URL}/api/v1/settings/ai-indexing/stats`, {
        params: { org_id: orgId },
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });
      return response.data;
    } catch (error: any) {
      // Handle errors gracefully without triggering main app token refresh
      // The docnet API has different authentication than doc2app
      if (error?.response?.status === 401) {
        console.warn('[FulltextSettings] AI indexing stats API returned 401 - docnet auth may need configuration');
      }
      throw new Error('Failed to load AI indexing statistics');
    }
  }

  /**
   * Get document indexing statistics for the organization
   *
   * Returns counts of documents in database, indexed, with vector, and text-only.
   *
   * @returns Promise with document stats
   */
  public async getDocumentStats(): Promise<DocumentStatsResponse> {
    const formData = new FormData();
    return super.post(
      `${FULL_TEXT_SEARCH_API_URL}/opensearch/documents/stats`,
      formData
    );
  }

  /**
   * Drop the cached search-result entries for the org.
   *
   * Bug-24 (2026-04-23): the dashboard caches `search_dashboard_ids`
   * responses for 3 minutes server-side. The web app's refresh-table
   * button calls this endpoint BEFORE re-fetching so the user always
   * sees a fresh OpenSearch read after an explicit refresh.
   *
   * Document mutations (insert / delete / update) already invalidate
   * automatically — this is the manual escape hatch for "I see stale
   * data, just refresh now".
   *
   * Returns 200 even if the cache was empty so callers can fire it
   * unconditionally on every refresh-button click.
   */
  public async invalidateSearchCache(): Promise<{ success: boolean; message?: string }> {
    const formData = new FormData();
    return super.post(
      `${FULL_TEXT_SEARCH_API_URL}/opensearch/search/invalidate`,
      formData
    );
  }

  /**
   * Rebuild document index
   *
   * @param mode - 'sync' for incremental (missing only), 'full' for complete rebuild
   * @param background - If true, run as Celery background task (returns task_id)
   * @returns Promise with reindex results
   */
  public async rebuildDocumentIndex(
    mode: 'sync' | 'full' = 'sync',
    background: boolean = false
  ): Promise<BulkReindexResponse> {
    const formData = new FormData();
    formData.append('mode', mode);
    if (background) {
      formData.append('background', 'true');
    }
    return super.post(
      `${FULL_TEXT_SEARCH_API_URL}/opensearch/bulk_reindex`,
      formData
    );
  }

  /**
   * Get current reindex progress for the organization
   *
   * Use this to poll for progress during bulk reindex operations.
   *
   * @returns Promise with current progress or null if no active reindex
   */
  public async getReindexProgress(): Promise<ReindexProgressResponse> {
    const formData = new FormData();
    return super.post(
      `${FULL_TEXT_SEARCH_API_URL}/opensearch/documents/reindex-progress`,
      formData
    );
  }

  /**
   * Strip every vector-embedding field from every doc in this org's index.
   *
   * Bug 2026-05-02: backs the "Disable + Delete embeddings" choice from
   * the new `DisableVectorConfirmDialog`. The pref-flag (
   * `OPENSEARCH_VECTOR_DOCUMENTS=false`) is flipped via the existing
   * `/admin/erp-settings/update` endpoint earlier in the same flow;
   * this call is the storage-cleanup half. Text-only fields stay
   * intact so keyword search continues to work.
   */
  public async clearVectorEmbeddings(): Promise<{
    success: boolean;
    modified_count?: number;
    took_ms?: number;
    failures?: unknown[];
    message?: string;
  }> {
    const formData = new FormData();
    return super.post(
      `${FULL_TEXT_SEARCH_API_URL}/opensearch/admin/clear-vector-embeddings`,
      formData
    );
  }

  /**
   * Get the SSE stream URL for real-time reindex progress updates.
   *
   * Returns a URL that can be used with EventSource to receive
   * server-sent events instead of polling.
   *
   * @returns SSE stream URL with auth query parameters
   */
  public async getReindexProgressStreamURL(): Promise<string> {
    return this.getIndexStatusStreamURL();
  }

  /**
   * Build the SSE stream URL for live index status updates.
   *
   * The backend stream stays open until the client disconnects and
   * pushes a combined snapshot (reindex progress + document stats +
   * ERP stats). Open it once on page mount instead of polling.
   *
   * @returns SSE stream URL with auth query parameters
   */
  public async getIndexStatusStreamURL(): Promise<string> {
    const authStore = useAuthTokenStore();
    const userStore = useUserStore();
    const token = await authStore.getValidatedToken();
    const orgId = userStore.getOrgId();
    await whenRegionReady();
    return `${FULL_TEXT_SEARCH_API_URL}/opensearch/index/status/stream?org_id=${encodeURIComponent(orgId)}&token=${encodeURIComponent(token)}`;
  }

  /**
   * Get sync diagnostics explaining why documents aren't indexed
   *
   * @param sampleLimit - Maximum number of sample missing documents to return
   * @returns Promise with diagnostics breakdown and sample missing docs
   */
  public async getSyncDiagnostics(
    sampleLimit: number = 10
  ): Promise<SyncDiagnosticsResponse> {
    const formData = new FormData();
    formData.append('sample_limit', String(sampleLimit));
    return super.post(
      `${FULL_TEXT_SEARCH_API_URL}/opensearch/documents/sync-diagnostics`,
      formData
    );
  }
}

/**
 * Interface for document indexing statistics response
 */
/**
 * One backend component of the index pipeline (Postgres / Spaces / OpenSearch)
 * with its actual region and whether it matches the org's intended region.
 * `region`/`matches` are null when the region couldn't be parsed (rendered as
 * "unknown" rather than a false mismatch).
 */
export interface FulltextTopologyComponent {
  kind: string;
  host: string | null;
  datacenter: string | null;
  region: string | null;
  matches: boolean | null;
  // True for index-critical components (DB, OpenSearch). The Spaces OCR source
  // is non-critical.
  critical?: boolean;
  // 'error' = index-critical component in the wrong region (red); 'advisory' =
  // non-critical cross-region (amber, e.g. OCR source); null = aligned/unknown.
  severity?: 'error' | 'advisory' | null;
}

/**
 * Per-org index pipeline topology — powers the "Pipeline" tab so customers /
 * consultants can verify every component sits in the org's region. `all_match`
 * is false when any component is in the wrong region (e.g. the Ruiz incident:
 * org US but OpenSearch still on EU fra1).
 */
export interface FulltextTopology {
  org_region: string;
  all_match: boolean;
  database: FulltextTopologyComponent;
  opensearch: FulltextTopologyComponent;
  spaces: FulltextTopologyComponent;
}

export interface DocumentStatsResponse {
  success: boolean;
  org_id: string;
  index_name: string;
  stats: {
    in_database: number;
    total_indexed: number;
    with_vector: number;
    text_only: number;
    /**
     * Phase 5: number of docs in the heavy-text companion index
     * (`*_text_v1`).  Optional because pre-Phase-5 backends don't emit
     * it — UI degrades to "—" / N/A and the third lane explains the
     * backfill state via templateVersions.text instead.
     */
    text_companion_indexed?: number;
  };
  template_versions?: FulltextTemplateVersions | null;
  // Optional: pre-topology backends don't emit it — the Pipeline tab degrades
  // to an explanatory empty state.
  topology?: FulltextTopology | null;
  took: number;
  message?: string;
}

/**
 * Interface for bulk reindex response
 */
export interface BulkReindexResponse {
  success: boolean;
  message: string;
  mode: string;
  indexed: number;
  failed: number;
  total: number;
  errors: Array<{ doc_id: string; error: string }>;
  task_id?: string; // Present when background=true
}

/**
 * Interface for reindex progress response
 */
export interface ReindexProgressResponse {
  success: boolean;
  org_id: string;
  progress: {
    total: number;
    processed: number;
    indexed: number;
    failed: number;
    current_batch: number;
    status: 'running' | 'completed' | 'failed';
    percent_complete: number;
    updated_at: string;
    errors: Array<{ doc_id: string; error: string }>;
    // Bug 2026-05-02: backend's stale-watchdog injects a human-readable
    // `message` (e.g. "Worker lost — no progress update in 522s") when
    // it flips a stuck `running` status to `failed`. Used by the new
    // LastReindexFailureBanner to explain WHY the run failed.
    message?: string;
    // Mode of the run that failed/completed. Backend may add this
    // later; treat as optional now so the failure banner can fall
    // back to 'sync' for retry.
    mode?: 'sync' | 'full' | 'vectors';
    // Backend cache-instrumentation timestamp. Not displayed.
    __cached_on?: string;
  } | null;
  active: boolean;
  message?: string;
}

/**
 * Interface for sync diagnostics response
 */
export interface SyncDiagnosticsResponse {
  success: boolean;
  org_id: string;
  index_name: string;
  diagnostics: {
    total_in_database: number;
    total_indexed: number;
    missing_count: number;
    breakdown: {
      no_s3_file: number;
      processing_incomplete: number;
      indexing_failed: number;
      edoc_indexing_failed?: number;
    };
    sample_missing_docs: Array<{
      doc_id: string;
      filename?: string;
      status?: string;
      reason?: string;
      created_at?: string;
    }>;
    recent_failures: Array<{
      doc_id: string;
      filename?: string;
      status?: string;
      reason?: string;
      created_on?: string;
    }>;
    is_estimated?: boolean;
    sample_size?: number;
  };
  took: number;
  message?: string;
}

/**
 * Interface for AI agent indexing statistics
 */
export interface AIAgentStats {
  agent_id: string;
  agent_name: string;
  index_name: string;
  indexed_count: number;
  memory_enabled: boolean;
  is_system: boolean;
}

/**
 * Interface for the response from get AI indexing stats
 */
export interface AIIndexingStatsResponse {
  success: boolean;
  agents: AIAgentStats[];
  total_indexed: number;
  message?: string;
}
